-- A ticket edit sets every column, and a reply moves only updated_at. Projections
-- now rebuild only when a value they hold changes; their contents stay the same.

-- Inbox counts: a retime skips any created or updated bucket (day, month or year)
-- that the old and new times share, instead of taking one away and adding it back.
DROP TRIGGER IF EXISTS inbox_entry_retimed;
CREATE TRIGGER inbox_entry_retimed AFTER UPDATE OF created_at,updated_at ON inbox_entries WHEN (NEW.created_at IS NOT OLD.created_at OR NEW.updated_at IS NOT OLD.updated_at) AND NOT (NEW.conversation_id IS NOT OLD.conversation_id OR NEW.project_id IS NOT OLD.project_id OR NEW.group_id IS NOT OLD.group_id OR NEW.assigned_to IS NOT OLD.assigned_to OR NEW.unresolved IS NOT OLD.unresolved OR NEW.ai IS NOT OLD.ai OR NEW.snoozed IS NOT OLD.snoozed OR NEW.priority IS NOT OLD.priority OR NEW.status_category IS NOT OLD.status_category OR NEW.channel IS NOT OLD.channel OR NEW.status_id IS NOT OLD.status_id) BEGIN
 UPDATE inbox_counts SET total=total-1 WHERE rowid IN (SELECT t.rowid FROM (SELECT 'c' family,'y' k1,CAST(strftime('%Y',(CASE WHEN OLD.created_at>=0 THEN OLD.created_at/86400000 ELSE (OLD.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)+0 k2 WHERE (typeof(OLD.created_at)='integer' AND OLD.created_at BETWEEN -4398046511104 AND 4398046511104) AND NOT (typeof(NEW.created_at)='integer' AND NEW.created_at BETWEEN -4398046511104 AND 4398046511104 AND CAST(strftime('%Y',(CASE WHEN OLD.created_at>=0 THEN OLD.created_at/86400000 ELSE (OLD.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)+0=CAST(strftime('%Y',(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)+0) UNION ALL SELECT 'c' family,'m' k1,(CAST(strftime('%Y',(CASE WHEN OLD.created_at>=0 THEN OLD.created_at/86400000 ELSE (OLD.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)*12+CAST(strftime('%m',(CASE WHEN OLD.created_at>=0 THEN OLD.created_at/86400000 ELSE (OLD.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)-1) k2 WHERE (typeof(OLD.created_at)='integer' AND OLD.created_at BETWEEN -4398046511104 AND 4398046511104) AND NOT (typeof(NEW.created_at)='integer' AND NEW.created_at BETWEEN -4398046511104 AND 4398046511104 AND (CAST(strftime('%Y',(CASE WHEN OLD.created_at>=0 THEN OLD.created_at/86400000 ELSE (OLD.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)*12+CAST(strftime('%m',(CASE WHEN OLD.created_at>=0 THEN OLD.created_at/86400000 ELSE (OLD.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)-1)=(CAST(strftime('%Y',(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)*12+CAST(strftime('%m',(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END)*86400,'unixepoch') AS INTEGER)-1)) UNION ALL SELECT 'c' family,'d' k1,(CASE WHEN OLD.created_at>=0 THEN OLD.created_at/86400000 ELSE (OLD.created_at+1)/86400000-1 END) k2 WHERE (typeof(OLD.created_at)='integer' AND OLD.created_at BETWEEN -4398046511104 AND 4398046511104) AND NOT (typeof(NEW.created_at)='integer' AND NEW.created_at BETWEEN -4398046511104 AND 4398046511104 AND (CASE WHEN OLD.created_at>=0 THEN OLD.created_at/86400000 ELSE (OLD.created_at+1)/86400000-1 END)=(CASE WHEN NEW.created_at>=0 THEN NEW.created_at/86400000 ELSE (NEW.created_at+1)/86400000-1 END))) s CROSS JOIN json_each('["","status_category","status_id","assigned_to","priority","channel","sa","sia","*"]') sl CROSS JOIN inbox_counts t ON t.project_id=OLD.project_id AND t.family=s.family AND t.slot=sl.value AND t.k1=s.k1 AND t.k2=s.k2 AND t.status_category IS CASE WHEN sl.value IN ('*','status_category','status_id','priority','sa','sia') THEN OLD.status_category END AND t.status_id IS CASE WHEN sl.value IN ('*','status_id','sia') THEN OLD.status_id END AND t.assigned_to IS CASE WHEN sl.value IN ('*','assigned_to','sa','sia') THEN OLD.assigned_to END AND t.priority IS CASE WHEN sl.value IN ('*','priority') THEN OLD.priority END AND t.channel IS CASE WHEN sl.value IN ('*','channel') THEN OLD.channel END AND t.snoozed=OLD.snoozed AND t.unresolved=OLD.unresolved AND t.ai=OLD.ai AND t.group_id IS OLD.group_id);
