-- Report cohorts: rebuild the cohort row and its workload items only when one of
-- the columns they are built from changes value.
DROP TRIGGER IF EXISTS reporting_conversation_update;
CREATE TRIGGER reporting_conversation_update AFTER UPDATE OF project_id,created_at,status_category,assigned_to,group_id,brand_id,channel,contact_id ON conversations
 WHEN NEW.project_id IS NOT OLD.project_id OR NEW.created_at IS NOT OLD.created_at OR NEW.status_category IS NOT OLD.status_category OR NEW.assigned_to IS NOT OLD.assigned_to
 OR NEW.group_id IS NOT OLD.group_id OR NEW.brand_id IS NOT OLD.brand_id OR NEW.channel IS NOT OLD.channel OR NEW.contact_id IS NOT OLD.contact_id BEGIN
 DELETE FROM reporting_conversations WHERE conversation_id=OLD.id;
 INSERT INTO reporting_conversations(conversation_id,project_id,created_at,status_category)
 SELECT NEW.id,NEW.project_id,NEW.created_at,NEW.status_category
 WHERE EXISTS(SELECT 1 FROM messages m WHERE m.project_id=NEW.project_id AND m.conversation_id=NEW.id);
END;
